class Solution {
    int[][] score;
    int[] memo;
    private int dfs(int mask){
        if(mask==memo.length-1)return 0;
        if(memo[mask]>=0)return memo[mask];
        int student=Integer.bitCount(mask),best=0;
        for(int mentor=0;mentor<score.length;mentor++)if((mask&(1<<mentor))==0)best=Math.max(best,score[student][mentor]+dfs(mask|1<<mentor));
        return memo[mask]=best;
    }
    public int maxCompatibilitySum(int[][] students,int[][] mentors){
        int n=students.length;
        score=new int[n][n];
        for(int i=0;i<n;i++)for(int j=0;j<n;j++)for(int q=0;q<students[i].length;q++)if(students[i][q]==mentors[j][q])score[i][j]++;
        memo=new int[1<<n];
        Arrays.fill(memo,-1);
        return dfs(0);
    }
}

code.kotlin:
class Solution {
    private lateinit var score:Array<IntArray>;
    private lateinit var memo:IntArray;
    private fun dfs(mask:Int):Int{
        if(mask==memo.lastIndex)return 0;
        if(memo[mask]>=0)return memo[mask];
        val student=Integer.bitCount(mask);
        var best=0;
        for(mentor in score.indices)if(mask and (1 shl mentor)==0)best=maxOf(best,score[student][mentor]+dfs(mask or (1 shl mentor)));
        memo[mask]=best;
        return best
    };
    fun maxCompatibilitySum(students:Array<IntArray>,mentors:Array<IntArray>):Int{
        val n=students.size;
        score=Array(n){
            student->IntArray(n){
                mentor->students[student].indices.count{
                    students[student][it]==mentors[mentor][it]
                }
            }
        };
        memo=IntArray(1 shl n){
            -1
        };
        return dfs(0)
    }
}

